From f552f929c7f36098cf074cc6ee358c91bf9badf6 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 20:03:57 +0100
Subject: [PATCH] applets/notes: allow one Sticky Note widget to hold several
 notes

Each widget could only show a single note, so keeping a few notes behind
one panel icon meant adding a widget for each. The toolbar now has a
button to add a note and arrows to move between the notes of the widget.

BUG: 489512
---
 applets/notes/main.xml     |   4 ++
 applets/notes/qml/main.qml | 122 +++++++++++++++++++++++++++++++++----
 2 files changed, 115 insertions(+), 11 deletions(-)

diff --git a/applets/notes/main.xml b/applets/notes/main.xml
index 552e3c2fd..a235af180 100644
--- a/applets/notes/main.xml
+++ b/applets/notes/main.xml
@@ -18,6 +18,10 @@
       <default></default>
     </entry>

+    <entry name="noteIds" type="StringList">
+      <default></default>
+    </entry>
+
     <entry name="scrollX" type="Double">
       <default>0</default>
     </entry>
diff --git a/applets/notes/qml/main.qml b/applets/notes/qml/main.qml
index 63a6409ba..803fb68c6 100644
--- a/applets/notes/qml/main.qml
+++ b/applets/notes/qml/main.qml
@@ -43,7 +43,57 @@ PlasmoidItem {
     // In a panel when it is translucent, the panel background is used, so we use the normal text color, and remove any margins.
     property bool noBackground: false // binding in onCompleted to avoid binding loop

-    property Note note: noteManager.loadNote(Plasmoid.configuration.noteId, Plasmoid.id);
+    // All notes of this widget; noteId is the one shown
+    readonly property list<string> storedNoteIds: Plasmoid.configuration.noteIds.length > 0 ? Plasmoid.configuration.noteIds : [Plasmoid.configuration.noteId]
+    property var notes: storedNoteIds.map(id => noteManager.loadNote(id, Plasmoid.id))
+    property int currentNoteIndex: 0
+    readonly property Note note: notes[currentNoteIndex]
+
+    function saveNoteIds() {
+        // Plasmoid configuration doesn't check before emitting change signal
+        // explicit check is needed (at time of writing)
+        const ids = notes.map(note => note.id);
+        if (ids.join() != Plasmoid.configuration.noteIds.join()) {
+            Plasmoid.configuration.noteIds = ids;
+        }
+        if (note.id != Plasmoid.configuration.noteId) {
+            Plasmoid.configuration.noteId = note.id;
+        }
+    }
+
+    function showNote(index) {
+        currentNoteIndex = index;
+        saveNoteIds();
+        mainTextArea.text = note.noteText;
+        mainTextArea.cursorPosition = 0;
+        mainTextArea.forceActiveFocus();
+    }
+
+    function addNote() {
+        note.save(mainTextArea.text);
+        const index = currentNoteIndex + 1;
+        const newNotes = notes.slice();
+        newNotes.splice(index, 0, noteManager.loadNote("", Plasmoid.id));
+        notes = newNotes;
+        showNote(index);
+    }
+
+    function switchNote(offset) {
+        note.save(mainTextArea.text);
+        showNote((currentNoteIndex + offset + notes.length) % notes.length);
+    }
+
+    function removeNote() {
+        if (notes.length < 2) {
+            Plasmoid.internalAction("remove").trigger();
+            return;
+        }
+        const removedNote = note;
+        currentNoteIndex = Math.min(currentNoteIndex, notes.length - 2);
+        notes = notes.filter(note => note !== removedNote);
+        noteManager.deleteNoteResources(removedNote.id);
+        showNote(currentNoteIndex);
+    }

     // define colors used for icons in ToolButtons and for text in TextArea.
     // this is deliberately _NOT_ the theme color as we are over a known bright background!
@@ -102,7 +152,7 @@ PlasmoidItem {

     Component.onDestruction: {
         if (scheduledForDestruction) {
-            noteManager.deleteNoteResources(note.id);
+            notes.forEach(note => noteManager.deleteNoteResources(note.id));
         } else {
             note.save(mainTextArea.text);
         }
@@ -495,7 +545,7 @@ PlasmoidItem {
                 opacity: (focusScope.activeFocus || root.compactInPanel) ? 1 : 0
                 Behavior on opacity { NumberAnimation { duration: Kirigami.Units.longDuration } }

-                readonly property int requiredWidth: spacing * (children.length - 1) + formatButtonsRow.width + removeButton.width
+                readonly property int requiredWidth: spacing * (children.length - 1) + formatButtonsRow.width + noteButtonsRow.width + removeButton.width
                                                      + spacer.implicitWidth + settingsButton.width + (root.compactInPanel ? pinButton.width : 0)
                 readonly property bool showFormatButtons: width > requiredWidth

@@ -565,6 +615,57 @@ PlasmoidItem {
                     Layout.fillHeight: true
                 }

+                Row {
+                    id: noteButtonsRow
+                    spacing: Kirigami.Units.smallSpacing
+
+                    PlasmaComponents3.ToolButton {
+                        visible: root.notes.length > 1
+                        focusPolicy: Qt.TabFocus
+                        icon.name: mirrored ? "go-next" : "go-previous"
+                        icon.color: root.textIconColor
+                        onClicked: root.switchNote(-1)
+                        text: previousTooltip.text
+                        display: PlasmaComponents3.AbstractButton.IconOnly
+                        PlasmaComponents3.ToolTip {
+                            id: previousTooltip
+                            text: i18nc("@info:tooltip", "Previous Note")
+                        }
+                    }
+                    PlasmaComponents3.Label {
+                        visible: root.notes.length > 1
+                        height: parent.height
+                        verticalAlignment: Text.AlignVCenter
+                        color: root.textIconColor
+                        text: i18nc("@info:status current note number and number of notes", "%1/%2", root.currentNoteIndex + 1, root.notes.length)
+                    }
+                    PlasmaComponents3.ToolButton {
+                        visible: root.notes.length > 1
+                        focusPolicy: Qt.TabFocus
+                        icon.name: mirrored ? "go-previous" : "go-next"
+                        icon.color: root.textIconColor
+                        onClicked: root.switchNote(1)
+                        text: nextTooltip.text
+                        display: PlasmaComponents3.AbstractButton.IconOnly
+                        PlasmaComponents3.ToolTip {
+                            id: nextTooltip
+                            text: i18nc("@info:tooltip", "Next Note")
+                        }
+                    }
+                    PlasmaComponents3.ToolButton {
+                        focusPolicy: Qt.TabFocus
+                        icon.name: "list-add"
+                        icon.color: root.textIconColor
+                        onClicked: root.addNote()
+                        text: addTooltip.text
+                        display: PlasmaComponents3.AbstractButton.IconOnly
+                        PlasmaComponents3.ToolTip {
+                            id: addTooltip
+                            text: i18nc("@info:tooltip", "Add Note")
+                        }
+                    }
+                }
+
                 PlasmaComponents3.ToolButton {
                     id: removeButton
                     focusPolicy: Qt.TabFocus
@@ -586,7 +687,7 @@ PlasmoidItem {
                             // is done in the same way every time.
                             documentHandler.stripAndSimplify(mainTextArea.text) === documentHandler.strippedClipboardText()
                         ) {
-                            Plasmoid.internalAction("remove").trigger();
+                            root.removeNote();
                         } else {
                             discardConfirmationDialogLoader.open();
                         }
@@ -594,7 +695,7 @@ PlasmoidItem {
                     Accessible.name: removeTooltip.text
                     PlasmaComponents3.ToolTip {
                         id: removeTooltip
-                        text: Plasmoid.internalAction("remove").text
+                        text: root.notes.length > 1 ? i18nc("@info:tooltip", "Delete This Note") : Plasmoid.internalAction("remove").text
                     }
                 }

@@ -666,7 +767,7 @@ PlasmoidItem {

                 onButtonClicked: (button, role) => {
                     if (button === MessageDialog.Discard) {
-                        Plasmoid.internalAction("remove").trigger()
+                        root.removeNote()
                         visible = false;
                     }
                 }
@@ -721,11 +822,10 @@ PlasmoidItem {
     }

     Component.onCompleted: {
-        // Plasmoid configuration doesn't check before emitting change signal
-        // explicit check is needed (at time of writing)
-        if (note.id != Plasmoid.configuration.noteId) {
-            Plasmoid.configuration.noteId = note.id;
-        }
+        // load the notes only once
+        notes = notes.slice();
+        currentNoteIndex = Math.max(0, storedNoteIds.indexOf(Plasmoid.configuration.noteId));
+        saveNoteIds();

         // set imperatively to avoid binding loop during startup
         root.noBackground = Qt.binding(() => inPanel && (Plasmoid.configuration.color === "translucent" || Plasmoid.configuration.color === "translucent-light"))
-- 
